import re
R='/home/claude/'
NB=' '
def fr(s): return re.sub(r' ([:;?!])', NB+r'\1', s)
T={
'bretagne':('brittany',
 'Les rendez-vous 2026-2027 en Bretagne',
 '<p>L’été est la saison des grandes fêtes bretonnes : le <a href="../bretagne/quimper/">Festival de Cornouaille</a> anime Quimper chaque fin juillet, et le Festival interceltique de Lorient est annoncé du 30 juillet au 8 août 2027. Hors saison, la côte est plus calme et souvent plus spectaculaire, sous les tempêtes d’hiver.</p><p>À savoir avant de partir : à <a href="../bretagne/ploumanach/">Ploumanac’h</a>, le grand parking du Ranolien est gratuit toute l’année, et le <a href="../bretagne/gr34-sentier-des-douaniers/">sentier des douaniers</a> reste ouvert en hiver. À <a href="../bretagne/quimper/">Quimper</a>, le musée des Beaux-Arts est fermé pour travaux jusqu’à sa réouverture, annoncée pour 2027.</p>',
 'Brittany events in 2026-2027',
 '<p>Summer is the season for Brittany’s big festivals: the <a href="../brittany/quimper/">Festival de Cornouaille</a> fills Quimper every late July, and the Lorient Interceltic Festival is announced for 30 July to 8 August 2027. Out of season, the coast is quieter and often more dramatic, under the winter storms.</p><p>Good to know before you go: in <a href="../brittany/ploumanach/">Ploumanac’h</a>, the large Ranolien car park is free all year, and the <a href="../brittany/gr34-sentier-des-douaniers/">customs officers’ path</a> stays open in winter. In <a href="../brittany/quimper/">Quimper</a>, the Musée des Beaux-Arts is closed for works until it reopens, planned for 2027.</p>'),
'normandie':('normandy',
 'Les rendez-vous 2026-2027 en Normandie',
 '<p>Le grand événement à venir est l’<a href="../normandie/rouen/">Armada de Rouen</a>, du 17 au 27 juin 2027 : plus de 40 grands voiliers sur les quais de Seine, avec de nombreux bateaux à visiter gratuitement. À <a href="../normandie/bayeux/">Bayeux</a>, la Tapisserie est exposée au British Museum de Londres jusqu’au 11 juillet 2027.</p><p>En hiver, l’abbaye du <a href="../normandie/mont-saint-michel/">Mont-Saint-Michel</a> ouvre de 9 h 30 à 18 h et le Mont est bien moins fréquenté. À <a href="../normandie/etretat/">Étretat</a>, plusieurs passages des falaises sont interdits depuis avril 2025 à cause du risque d’éboulement, dont le Trou à l’Homme.</p>',
 'Normandy events in 2026-2027',
 '<p>The big upcoming event is the <a href="../normandy/rouen/">Rouen Armada</a>, from 17 to 27 June 2027: more than 40 tall ships along the Seine, many of them open to visit for free. In <a href="../normandy/bayeux/">Bayeux</a>, the Tapestry is on show at the British Museum in London until 11 July 2027.</p><p>In winter, the <a href="../normandy/mont-saint-michel/">Mont-Saint-Michel</a> abbey opens from 9.30am to 6pm and the Mont is far less crowded. In <a href="../normandy/etretat/">Étretat</a>, several cliff passages have been off limits since April 2025 because of the risk of rockfall, including the Trou à l’Homme.</p>'),
'alsace':('alsace',
 'L’Alsace en dehors des marchés de Noël',
 '<p>Les marchés ouvrent le 23 novembre 2026 à <a href="../alsace/colmar/">Colmar</a> et le 27 novembre à <a href="../alsace/strasbourg/">Strasbourg</a>, <a href="../alsace/riquewihr/">Riquewihr</a> et <a href="../alsace/kaysersberg/">Kaysersberg</a> ; notre <a href="../idees/marches-de-noel-alsace/">itinéraire des marchés de Noël</a> donne toutes les dates. Mais la région se visite toute l’année.</p><p>À Strasbourg, montez à la plateforme de la cathédrale, à 66 m de haut, et assistez au défilé des apôtres de l’horloge astronomique à 12 h 30. À Colmar, le musée Unterlinden abrite le retable d’Issenheim. Entre les deux, le château du Haut-Koenigsbourg domine la plaine d’Alsace.</p>',
 'Alsace beyond the Christmas markets',
 '<p>The markets open on 23 November 2026 in <a href="../alsace/colmar/">Colmar</a> and on 27 November in <a href="../alsace/strasbourg/">Strasbourg</a>, <a href="../alsace/riquewihr/">Riquewihr</a> and <a href="../alsace/kaysersberg/">Kaysersberg</a>; our <a href="../ideas/alsace-christmas-markets/">Christmas markets itinerary</a> has all the dates. But the region is worth a visit all year round.</p><p>In Strasbourg, climb to the cathedral platform, 66 metres up, and watch the astronomical clock’s procession of the apostles at 12.30pm. In Colmar, the Musée Unterlinden is home to the Isenheim Altarpiece. Between the two, the Haut-Koenigsbourg castle towers over the Alsace plain.</p>'),
'pays-basque':('basque-country',
 'Le Pays basque au fil de l’année',
 '<p>L’été, les <a href="../pays-basque/bayonne/">Fêtes de Bayonne</a> habillent la ville de blanc et de rouge fin juillet, et le petit train de <a href="../pays-basque/la-rhune/">la Rhune</a> circule du printemps à l’automne : il reprend le 28 mars 2027. Fin octobre, <a href="../pays-basque/espelette/">Espelette</a> fête son piment pendant un week-end.</p><p>En hiver, la côte reste vivante : on surfe toute l’année à <a href="../pays-basque/biarritz/">Biarritz</a>, et les marchés continuent, le mercredi matin à Espelette et le lundi matin à <a href="../pays-basque/saint-jean-pied-de-port/">Saint-Jean-Pied-de-Port</a>.</p>',
 'The Basque Country through the year',
 '<p>In summer, the <a href="../basque-country/bayonne/">Bayonne festival</a> dresses the town in white and red in late July, and the little train up <a href="../basque-country/la-rhune/">La Rhune</a> runs from spring to autumn: it starts again on 28 March 2027. In late October, <a href="../basque-country/espelette/">Espelette</a> celebrates its pepper for a weekend.</p><p>In winter, the coast stays lively: you can surf all year round in <a href="../basque-country/biarritz/">Biarritz</a>, and the markets carry on, on Wednesday mornings in Espelette and Monday mornings in <a href="../basque-country/saint-jean-pied-de-port/">Saint-Jean-Pied-de-Port</a>.</p>'),
'corse':('corsica',
 'Quand partir en Corse',
 '<p>De juin à septembre, c’est la saison des plages et des sorties en mer : pour les <a href="../corse/iles-lavezzi/">îles Lavezzi</a>, les <a href="../corse/falaises-de-bonifacio/">falaises de Bonifacio</a> ou Scandola depuis <a href="../corse/calvi/">Calvi</a>, réservez votre bateau à l’avance. Les parkings des plages de <a href="../corse/porto-vecchio/">Porto-Vecchio</a> et de la route des <a href="../corse/piana/">calanques de Piana</a> se remplissent vite.</p><p>Hors saison, l’île est bien plus calme : citadelles, vieux ports et vieilles villes restent en accès libre toute l’année, à <a href="../corse/bastia/">Bastia</a>, Calvi ou Bonifacio. À <a href="../corse/ajaccio/">Ajaccio</a>, la Maison Bonaparte ouvre avec des horaires réduits en hiver.</p>',
 'When to go to Corsica',
 '<p>From June to September, it is beach and boat-trip season: for the <a href="../corsica/iles-lavezzi/">Lavezzi islands</a>, the <a href="../corsica/falaises-de-bonifacio/">Bonifacio cliffs</a> or Scandola from <a href="../corsica/calvi/">Calvi</a>, book your boat in advance. The beach car parks around <a href="../corsica/porto-vecchio/">Porto-Vecchio</a> and along the road to the <a href="../corsica/piana/">Calanques de Piana</a> fill up fast.</p><p>Out of season, the island is much quieter: citadels, old harbours and old towns are open all year round, in <a href="../corsica/bastia/">Bastia</a>, Calvi or Bonifacio. In <a href="../corsica/ajaccio/">Ajaccio</a>, the Maison Bonaparte keeps shorter opening hours in winter.</p>'),
}
for fr_dir,(en_dir,t1,b1,t2,b2) in T.items():
    for path,title,body,isfr,slug in ((R+'clicandsite-guide/'+fr_dir+'/index.html',t1,b1,True,fr_dir),(R+'clicandsite-guide-en/'+en_dir+'/index.html',t2,b2,False,en_dir)):
        s=open(path).read()
        if 'id="g-annee"' in s: print('skip',path); continue
        sec=f'<section class="wrap prose" aria-labelledby="g-annee"><h2 id="g-annee" class="sec-title">{title}</h2>{body}</section>\n'
        if isfr: sec=fr(sec)
        k=s.rindex('</main>'); s=s[:k]+sec+'\n'+s[k:]
        open(path,'w').write(s); print('ok',path)
